// No IP, UA, referrer or session id leaves this node. The session id keys an in-memory 60-s rate window only.
const L = require('lv-automation').subVisitBeacon;
const it = $input.first().json;
const ev = L.normalise({ body: it.body, headers: it.headers || {}, env: $env });
if (!ev.ok) return { json: { accept: false, reason: ev.reason } };
const sd = $getWorkflowStaticData('global');
const r = L.rateLimit(sd.rate, ev.sid, Date.now());
sd.rate = r.state;
if (!r.allowed) return { json: { accept: false, reason: r.reason } };
return { json: { accept: true, inc: L.increment(ev, Date.now(), $env.BRAND_ID) } };
